private void addExtendsClauseNames(JCTree type, HashSet<String> usedNames) {
	if (type instanceof JCIdent) {
		usedNames.add(type.toString());
	} else if (type instanceof JCFieldAccess) {
		addExtendsClauseNames(((JCFieldAccess) type).selected, usedNames);
		usedNames.add(((JCFieldAccess) type).name.toString());
	} else if (type instanceof JCTypeApply) {
		addExtendsClauseNames(((JCTypeApply) type).getType(), usedNames);
		for (JCTree arg : ((JCTypeApply) type).getTypeArguments()) addExtendsClauseNames(arg, usedNames);
	} else if (type instanceof JCWildcard) {
		addExtendsClauseNames(((JCWildcard) type).getInner(), usedNames);
	}
}

private String generateNonclashingNameFor(String classGenericName, java.util.HashSet<String> typeParamStrings) {
	if (!typeParamStrings.contains(classGenericName)) return classGenericName;
	int counter = 2;
	while (typeParamStrings.contains(classGenericName + counter)) counter++;
	return classGenericName + counter;
}

