	if (type == null) return;
	if (type instanceof Wildcard) {
		addExtendsClauseNames(((Wildcard) type).bound, usedNames);
		return;
	}
	char[][] typeName = type.getTypeName();
	if (typeName != null && typeName.length >= 1)
		usedNames.add(String.valueOf(typeName[typeName.length - 1]));
	if (type instanceof ParameterizedSingleTypeReference) {
		if (((ParameterizedSingleTypeReference) type).typeArguments != null)
			for (TypeReference arg : ((ParameterizedSingleTypeReference) type).typeArguments)
				addExtendsClauseNames(arg, usedNames);
